const D = { energy:.62, scale:1, speed:1, density:.55, wobble:.55, hue:32, x:.5, y:.5, style:'sepia', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// ASEMIC HAND — an invisible scribe writing invented cursive script, stroke by
// stroke, line by line, down a toned parchment page. Nonsense-glyph flowing hand:
// baseline wander with ascenders, descenders and loops, nib-pressure weight and
// ink pooling at pen-dwell. A soft raking light travels across the sheet; when
// the page fills it is set aside and a fresh sheet, a new hand, begins — a
// perpetual scriptorium that never settles. Sepia iron-gall, indigo, charcoal,
// or a chalk-on-blueprint negative.
// -----------------------------------------------------------------------------

const wh = h => ((h % 360) + 360) % 360;
const style = P.style;
const BW = Math.max(360, Math.min(760, Math.round(width / 2.4)));
const BH = Math.max(200, Math.round(BW * height / width));
const key = BW + 'x' + BH;
const eseed = (P.seed | 0) * 1009 + (S.page || 0) * 131;
const fr = i => { const s = Math.sin(i * 127.1 + eseed * 0.917 + 11.3) * 43758.5453; return s - Math.floor(s); };

// palette per style: [paperH,paperS,paperB, inkH,inkS,inkB, negative?]
function pal() {
  if (style === 'indigo')    return { pH:222, pS:22, pB:54, iH:224, iS:62, iB:20, neg:0, light:[44,55,100] };
  if (style === 'charcoal')  return { pH:38,  pS:9,  pB:52, iH:30,  iS:8,  iB:14, neg:0, light:[40,25,100] };
  if (style === 'blueprint') return { pH:210, pS:55, pB:26, iH:190, iS:12, iB:94, neg:1, light:[195,40,100] };
  return { pH:wh(P.hue+6), pS:32, pB:50, iH:wh(P.hue-8), iS:60, iB:20, neg:0, light:[44,60,100] }; // sepia
}
const C = pal();

// ---- (re)build parchment ground + line ruling -------------------------------
if (!S.paper || S.pkey !== key || S.pstyle !== style || S.pseed !== (P.seed|0)) {
  S.pkey = key; S.pstyle = style; S.pseed = (P.seed|0);
  const pg = createGraphics(BW, BH); pg.colorMode(HSB, 360, 100, 100, 100); pg.noStroke();
  pg.background(C.pH, C.pS, C.pB);
  // broad mottle / uneven toning
  pg.blendMode(C.neg ? ADD : MULTIPLY);
  for (let i = 0; i < 90; i++) {
    const mx = fr(i*3+1)*BW, my = fr(i*5+2)*BH, mr = BW*(0.12+fr(i*7+3)*0.34);
    const d = C.neg ? 6+fr(i)*10 : 100-(6+fr(i)*12);
    pg.fill(C.pH, C.pS*0.7, C.neg ? d+40 : d, 10); pg.ellipse(mx, my, mr, mr*0.8);
  }
  // foxing / age stains
  pg.blendMode(BLEND);
  for (let i = 0; i < 22; i++) {
    const fx = fr(i*11+40)*BW, fy = fr(i*13+41)*BH;
    pg.fill(C.neg ? 200 : 26, C.neg?30:38, C.neg?34:44, 8+fr(i*3+9)*12);
    pg.ellipse(fx, fy, BW*(0.03+fr(i*9+7)*0.08), BW*(0.03+fr(i*9+8)*0.08));
  }
  // fine tooth / grain
  for (let i = 0; i < 2600; i++) {
    const gx = fr(i*2.1+900)*BW, gy = fr(i*3.7+901)*BH;
    pg.fill(C.pH, C.pS, C.neg ? C.pB+fr(i)*22 : C.pB-fr(i)*24, 6);
    pg.rect(gx, gy, 1.2, 1.2);
  }
  S.paper = pg;

  // vignette (baked once, blitted MULTIPLY on top)
  const vg = createGraphics(BW, BH); vg.colorMode(HSB, 360, 100, 100, 100); vg.clear();
  const gctx = vg.drawingContext;
  const rg = gctx.createRadialGradient(BW/2, BH/2, BH*0.25, BW/2, BH/2, BH*0.85);
  rg.addColorStop(0, 'rgba(0,0,0,0)'); rg.addColorStop(0.6, 'rgba(0,0,0,0.10)'); rg.addColorStop(1, 'rgba(0,0,0,0.48)');
  gctx.fillStyle = rg; gctx.fillRect(0, 0, BW, BH);
  S.vig = vg;
}

// ---- (re)build the page's stroke structure ----------------------------------
const dens = P.density;
const marginX = BW * 0.10, marginTop = BH * 0.11, marginBot = BH * 0.90;
const lineH = BH * (0.070 - dens * 0.024) / Math.max(0.55, P.scale*0.9 + 0.1);
const xh = lineH * 0.42;
const nLines = Math.max(4, Math.floor((marginBot - marginTop) / lineH));
if (!S.strokes || S.skey !== key || S.sstyle !== style || S.spage !== (S.page||0) || S.sseed !== (P.seed|0) || S.sdens !== Math.round(dens*20) || S.sscale !== Math.round(P.scale*20)) {
  S.skey = key; S.sstyle = style; S.spage = (S.page||0); S.sseed = (P.seed|0); S.sdens = Math.round(dens*20); S.sscale = Math.round(P.scale*20);
  const strokes = [];
  const letterW = xh * 0.9;
  let gi = 0;
  for (let li = 0; li < nLines; li++) {
    const yb = marginTop + xh + li * lineH;
    // ragged right margin
    const rightX = BW * (0.86 - fr(li*17+3) * 0.10);
    let x = marginX + fr(li*7+1) * BW * 0.01;
    // first-line rubric flag (a coloured initial word)
    let firstWord = true;
    while (x < rightX - letterW * 2) {
      const wLetters = 2 + Math.floor(fr(gi*3.3+li*5+2) * 7);
      const wWidth = wLetters * letterW * (0.85 + fr(gi*2+9)*0.3);
      if (x + wWidth > rightX) break;
      // build a cursive polyline for this word
      const pts = [];
      const steps = Math.max(6, Math.round(wWidth / (letterW * 0.34)));
      let ph1 = fr(gi*5+li+7) * 6.28, ph2 = fr(gi*9+li+3) * 6.28;
      for (let s = 0; s <= steps; s++) {
        const f = s / steps;
        const px = x + wWidth * f;
        let py = yb - xh * (0.34 + 0.30 * Math.sin(f * wLetters * 3.0 + ph1) + 0.18 * Math.sin(f * wLetters * 6.4 + ph2)) * (0.6 + P.wobble);
        // occasional ascender / descender at letter boundaries
        const lb = f * wLetters;
        const near = Math.abs(lb - Math.round(lb));
        if (near < 0.12) {
          const r = fr(gi*13 + Math.round(lb) * 3 + li);
          if (r > 0.80) py -= xh * (0.9 + fr(gi+7)*0.5);       // ascender
          else if (r < 0.16) py += xh * (0.8 + fr(gi+8)*0.5);  // descender
        }
        pts.push({ x: px, y: py });
      }
      const rub = (firstWord && fr(li*3+5) > 0.55 && !C.neg);
      strokes.push({ pts, line: li, w: 0.7 + fr(gi*4+1)*0.7, rub });
      firstWord = false;
      x += wWidth + letterW * (0.7 + fr(gi*6+4) * 0.9);   // inter-word space
      gi++;
    }
  }
  S.strokes = strokes; S.drawn = 0; S.prog = 0;
  const ig = createGraphics(BW, BH); ig.colorMode(HSB, 360, 100, 100, 100); ig.clear();
  S.ink = ig; S.phase = 'write'; S.dwell = 0; S.fade = 100;
}

// draw one stroke permanently into the ink buffer
function inkStroke(g, st, frac) {
  const pts = st.pts; if (pts.length < 2) return;
  const n = Math.max(2, Math.round(pts.length * frac));
  const iH = st.rub ? wh(P.hue - 190) : C.iH, iS = st.rub ? 62 : C.iS, iB = st.rub ? 40 : C.iB;
  const dark = 0.4 + P.energy * 0.85;
  g.noFill();
  for (let i = 1; i < n; i++) {
    const a = pts[i-1], b = pts[i];
    const down = Math.max(0, (b.y - a.y)) / (xh + 0.001);          // down-strokes heavier
    const wgt = st.w * (0.55 + 1.15 * Math.min(1, down * 1.4)) * (0.7 + P.scale*0.5);
    g.strokeWeight(Math.max(0.5, wgt));
    g.stroke(iH, iS, C.neg ? Math.min(100, iB) : iB, Math.min(100, 60 + dark*40));
    g.line(a.x, a.y, b.x, b.y);
  }
  // ink pooling at ends + at the deepest descender
  g.noStroke(); g.fill(iH, iS, iB, 55);
  g.ellipse(pts[0].x, pts[0].y, st.w*2.1, st.w*2.1);
  const e = pts[n-1]; g.ellipse(e.x, e.y, st.w*2.4, st.w*2.4);
}

// ---- advance the write-front ------------------------------------------------
const total = S.strokes.length;
const spd = 0.35 + P.speed * 1.15;
if (S.phase === 'write') {
  S.prog += (spd * 26) / (K.fps || 60);            // strokes per frame
  const upto = Math.min(total, Math.floor(S.prog));
  while (S.drawn < upto) { inkStroke(S.ink, S.strokes[S.drawn], 1); S.drawn++; }
  if (S.drawn >= total) { S.phase = 'dwell'; S.dwell = 0; }
} else if (S.phase === 'dwell') {
  S.dwell += 1 / (K.fps || 60);
  if (S.dwell > 2.6 / (0.4 + P.speed*0.8)) S.phase = 'fade';
} else if (S.phase === 'fade') {
  S.fade -= 130 / (K.fps || 60);
  if (S.fade <= 0) { S.page = (S.page || 0) + 1; S.strokes = null; }   // reseed next page
}

// ---- render -----------------------------------------------------------------
const t = K.t;
// slow incommensurate page drift (never re-phases) — keeps a live motion floor
const dx = Math.sin(t*0.13)*width*0.006 + Math.sin(t*0.31+1.1)*width*0.004;
const dy = Math.cos(t*0.11)*height*0.006 + Math.sin(t*0.27+0.5)*height*0.005;
const ox = (P.x - 0.5) * width * 0.14, oy = (P.y - 0.5) * height * 0.14;

push();
translate(dx + ox, dy + oy);
if (S.paper) image(S.paper, 0, 0, width, height);
if (S.ink)  { push(); tint(0,0,100, S.phase==='fade'? Math.max(0,S.fade) : 100); image(S.ink, 0, 0, width, height); pop(); }

// live "wet" leading stroke on the main canvas (crisp, full-res)
if (S.phase === 'write' && S.drawn < total) {
  const st = S.strokes[S.drawn];
  const frac = Math.min(1, S.prog - Math.floor(S.prog));
  const sxr = width / BW, syr = height / BH;
  const n = Math.max(2, Math.round(st.pts.length * frac));
  noFill();
  const wet = 0.5 + P.energy*0.6 + A.treble*0.4;
  for (let i = 1; i < n; i++) {
    const a = st.pts[i-1], b = st.pts[i];
    const down = Math.max(0, (b.y - a.y)) / (xh+0.001);
    strokeWeight(Math.max(0.6, st.w*(0.55+1.15*Math.min(1,down*1.4))*(0.7+P.scale*0.5)) * sxr);
    stroke(C.iH, C.iS, C.neg? Math.min(100, C.iB+8) : C.iB, 90);
    line(a.x*sxr, a.y*syr, b.x*sxr, b.y*syr);
  }
  // glistening nib
  const e = st.pts[n-1];
  noStroke(); fill(C.light[0], C.light[1]*0.4, C.light[2], 40*wet);
  ellipse(e.x*sxr, e.y*syr, 6*sxr, 6*syr);
}
pop();

// ---- raking illumination sweep (broad, low-alpha → carries the motion gate) --
const sweep = (Math.sin(t*0.19) * 0.5 + 0.5) * 0.55 + (Math.sin(t*0.052+2.0)*0.5+0.5)*0.45; // 0..1 incommensurate
const lx = sweep * width;
push(); blendMode(ADD); noStroke();
const bandW = width * 0.34;
const glow = (8 + P.energy * 12 + A.rms * 10) * (C.neg ? 0.7 : 1);
for (let b = 0; b < 5; b++) {
  const a = glow * (1 - b/5) * 0.5;
  fill(C.light[0], C.light[1]*(0.5+0.1*b), C.light[2], a);
  rect(lx - bandW/2, -height*0.05, bandW*(0.4+0.15*b), height*1.1);
}
// warm pool where the light peaks
fill(C.light[0], C.light[1]*0.7, C.light[2], glow*0.7);
ellipse(lx, height*0.5 + Math.sin(t*0.23)*height*0.12, bandW*0.5, height*0.7);
blendMode(BLEND); pop();

// vignette on top
if (S.vig) { push(); blendMode(MULTIPLY); image(S.vig, dx+ox, dy+oy, width, height); blendMode(BLEND); pop(); }

if (P.alpha < 100) { push(); noStroke(); fill(C.pH, C.pS, C.pB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
